void trace_events_disable ( struct trace_instance * instance , struct trace_events * events ) { struct trace_events * tevent = events ; while ( tevent ) { debug_msg ( "Disabling event %s:%s\n" , tevent -> system , tevent -> event ?: "*" ) ; if ( tevent -> enabled ) { trace_event_disable_filter ( instance , tevent ) ; trace_event_disable_trigger ( instance , tevent ) ; tracefs_event_disable ( instance -> inst , tevent -> system , tevent -> event ) ; } tevent -> enabled = 0 ; tevent = tevent -> next ; } } 